from collections import OrderedDict
class LRU:
    def __init__(self, cap): self.cap = cap; self.store = OrderedDict(); self.hits = 0; self.misses = 0
    def get(self, key):
        if key in self.store:
            self.store.move_to_end(key); self.hits += 1; return 'HIT'
        self.misses += 1
        self.store[key] = True
        evicted = None
        if len(self.store) > self.cap:
            evicted, _ = self.store.popitem(last=False)
        return 'MISS' + (' (evicted ' + evicted + ')' if evicted else '')
cache = LRU(3)
for key in ['A', 'B', 'C', 'A', 'D', 'B', 'A', 'E']:
    print(key, '->', cache.get(key), '| cache now:', list(cache.store))
print('hits:', cache.hits, 'misses:', cache.misses)
